    sizeof(kManagerFieldAccesses) / sizeof(kManagerFieldAccesses[0]);

inline std::size_t countManagerLiteralWrites(u16 offset) {
    std::size_t count = 0;
    for (const ManagerLiteralWrite& row : kManagerLiteralWrites)
        if (row.offset == offset) ++count;
    return count;
}

inline bool managerHasLiteralWrite(u16 offset, u32 value) {
    for (const ManagerLiteralWrite& row : kManagerLiteralWrites)
        if (row.offset == offset && row.value == value) return true;
    return false;
}

inline const ManagerAccessor* findManagerAccessor(u32 functionVa) {
    for (const ManagerAccessor& row : kManagerAccessors)
        if (row.functionVa == functionVa) return &row;
    return nullptr;
}

inline const ManagerAccessor* findManagerAccessorAt(u16 offset) {
    for (const ManagerAccessor& row : kManagerAccessors)
        if (row.offset == offset) return &row;
    return nullptr;
}

inline const ManagerFieldAccess* findManagerFieldAccess(
    u32 functionVa, u16 offset) {
    for (const ManagerFieldAccess& row : kManagerFieldAccesses)
        if (row.functionVa == functionVa && row.offset == offset)
            return &row;
    return nullptr;
}

